from fastapi import APIRouter, Depends, HTTPException
from pydantic import BaseModel
import duckdb
import re

router = APIRouter(prefix="/analytics/lakehouse")

class ParquetQueryRequest(BaseModel):
    dataset_path: str
    metric_column: str

@router.post("/aggregate")
async def aggregate_parquet_dataset(
    payload: ParquetQueryRequest,
    duck_conn: duckdb.DuckDBPyConnection = Depends(get_duckdb_session),
    current_user: User = Depends(get_current_user)
):
    expected_prefix = f"s3://prod-lakehouse-data/tenants/{current_user.tenant_id}/"
    if not payload.dataset_path.startswith(expected_prefix):
        raise HTTPException(status_code=403, detail="Forbidden: Dataset path is outside tenant boundary")

    if not re.match(r"^[a-zA-Z_][a-zA-Z0-9_]*$", payload.metric_column):
        raise HTTPException(status_code=400, detail="Invalid metric column name")

    query = f"SELECT count(*), avg({payload.metric_column}) FROM read_parquet(?)"
    try:
        result = duck_conn.execute(query, [payload.dataset_path]).fetchall()
    except Exception as e:
        raise HTTPException(status_code=400, detail=f"DuckDB query failed: {str(e)}")

    return {"dataset": payload.dataset_path, "summary": result}
